<?php
require_once 'includes/config.php'; require_once 'includes/phase3.php'; require_teacher();$tid=current_teacher_id();
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['mark_all'])){notification_mark_all_read($dbh,'teacher',$tid);header('Location: teacher-notifications.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['mark_id'])){$id=(int)$_POST['mark_id'];$q=$dbh->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=:id AND recipient_type=\'teacher\' AND recipient_id=:r');$q->execute([':id'=>$id,':r'=>$tid]);header('Location: teacher-notifications.php');exit;}
$q=$dbh->prepare('SELECT * FROM notifications WHERE recipient_type=\'teacher\' AND recipient_id=:r ORDER BY is_read ASC,created_at DESC LIMIT 100');$q->execute([':r'=>$tid]);$rows=$q->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teacher Notifications | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body><nav class="navbar navbar-default srms-mobile-nav"><div class="container-fluid"><a class="navbar-brand" href="teacher-dashboard.php"><?php echo e(srms_school_name());?></a><p class="navbar-text pull-right"><img src="profile-photo.php?type=teacher&id=<?php echo (int)($_SESSION['teacher_id']??0);?>" alt="Profile photo" width="28" height="28" style="border-radius:50%;object-fit:cover" onerror="this.style.display='none'"> <?php echo e($_SESSION['teacher_name']??'Teacher');?> · <a href="teacher-logout.php">Sign out</a></p></div></nav><div class="container-fluid srms-page"><div class="srms-toolbar"><a class="btn btn-default" href="teacher-dashboard.php">← Dashboard</a><form method="post" class="pull-right"><?php echo csrf_field();?><button class="btn btn-default" name="mark_all" value="1">Mark all read</button></form></div><h2>Notifications</h2><div class="panel"><div class="panel-body"><?php foreach($rows as $r):?><div style="padding:12px;border-bottom:1px solid #eee;background:<?php echo $r['is_read']?'#fff':'#f5f9ff';?>"><strong><?php echo e($r['title']);?></strong> — <?php echo e($r['message']);?><br><small class="text-muted"><?php echo e($r['created_at']);?></small><?php if(!$r['is_read']):?><form method="post" class="pull-right"><?php echo csrf_field();?><input type="hidden" name="mark_id" value="<?php echo $r['id'];?>"><button class="btn btn-xs btn-link">Mark read</button></form><?php endif;?><?php if($r['link']):?><a class="btn btn-xs btn-primary pull-right" href="<?php echo e($r['link']);?>">Open</a><?php endif;?></div><?php endforeach;?><?php if(!$rows):?><p class="text-center text-muted">No notifications.</p><?php endif;?></div></div></div></body></html>
